{
  "name": "@expitc/termad",
  "version": "0.1.5",
  "description": "Opt-in, fully reversible text ads for terminal AI CLIs (claude, codex, opencode, gemini). Consent-first, tamper-evident audit, 50% runner revenue share.",
  "type": "module",
  "license": "MIT",
  "author": "EXPITC",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/EXPITC/termad.git"
  },
  "bugs": {
    "url": "https://github.com/EXPITC/termad/issues"
  },
  "homepage": "https://github.com/EXPITC/termad#readme",
  "keywords": [
    "cli",
    "ads",
    "terminal",
    "claude",
    "codex",
    "opencode",
    "gemini",
    "statusline"
  ],
  "bin": {
    "termad": "dist/cli.js"
  },
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "files": [
    "dist",
    "assets",
    "scripts/ensure-pty-helper.mjs",
    "README.md",
    "POLICY.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "tsc && node scripts/copy-assets.mjs",
    "check:render": "node scripts/check-render.mjs",
    "check:overlay": "node scripts/check-overlay.mjs",
    "check:cli": "node scripts/check-cli.mjs",
    "dev": "tsc --watch",
    "server": "node server/server.mjs",
    "postinstall": "node scripts/ensure-pty-helper.mjs || exit 0",
    "prepublishOnly": "npm run build",
    "check:dashboard": "node scripts/check-dashboard.mjs"
  },
  "engines": {
    "node": ">=18"
  },
  "devDependencies": {
    "@types/node": "^22.10.0",
    "typescript": "^5.7.0"
  },
  "optionalDependencies": {
    "node-pty": "^1.1.0"
  },
  "allowScripts": {
    "node-pty@1.1.0": true
  }
}
